// brickfall: a brick breaker in a pane.
//
// The game runs here, in the hooks module: a timer steps it (game.ts), draws
// each frame (render.ts) and blits it onto the screen, a picture in kitty and
// Ghostty, quadrant cells elsewhere. The overlay (pad.ts) hands it the
// pointer and the keys. The best score is stored. No hook touches what the
// model reads: there is no prompt, tool or attachment hook in this mod.
//
// The host reads on(...) and $.noun.method(...) from source, so they are
// spelled literally, and helpers that take $ are top-level functions here.

import type { EngineInterface, ImageSource, Register, Timer } from 'claude-code'

import { aim, drainEvents, newGame, nudge, press, step, togglePause, W } from './game'
import type { Game } from './game'
import { BUTTONS, betterBest, bestOf, drawsImages, frameTicks, freshActs, hintFor, hudOf, hudText, nextPace, padOf, paneRequest, parseArgs, pixelsOf, rollScore, screenSize } from './lib'
import type { Act, Best, Pace, ScreenMode, Size } from './lib'
import type { PadProps } from './pad'
import { cellsOf, draw, makeCanvas, toCells, toRgba, base64 } from './render'
import type { Canvas } from './render'

const PANE = 'brickfall'
const TITLE = 'Brickfall'
const SCREEN = 'screen'
const STRIP = 'strip'
const LOOK = 'look'
const NO_SCREEN = 'Brickfall draws its field in the terminal only. In VS Code, run claude in the integrated terminal.'

const TICK_MS = 16
// Ticks between painted frames: a picture's bytes cross to the terminal with
// every frame, cells are small. Idle (nothing moving but the backdrop), fewer.
const IDLE_FRAME_TICKS = 4
const HUD_MS = 150
const AWAY_MS = 600
const FIT_SLACK = 2
const IMAGE_REFUSALS = 10
const HIDDEN_REFUSALS = 6

// A pane takes the keyboard only over an empty prompt, and a command's own
// text stays in the prompt while the command runs: the waits after /bricks
// returns before asking for the keyboard again, each tried only while the
// pane is open and still without it.
const FOCUS_RETRIES_MS = [250, 500, 1000] as const

// The game as the hooks know it. In memory; the best score is also stored.
const state: {
  game: Game | null
  best: Best
  mode: ScreenMode
  size: Size
  canvas: Canvas | null
  words: Uint32Array | null
  rgba: Uint8Array | null
  cells: string | null
  source: ImageSource | null
  drawnFor: string
  // How long a frame has lately taken to draw (ms), and the picture's
  // quality step with how long frames have been slow or quick at it.
  cost: number
  pace: Pace
  timer: Timer | null
  last: number
  ticks: number
  t0: number
  isPainting: boolean
  refusals: number
  seen: Record<PadProps['role'], number>
  awaySince: number | null
  isAutoPaused: boolean
  hud: string
  hudAt: number
  shown: number
  isFullscreen: boolean
  fittedTo: number | null
} = {
  game: null,
  best: null,
  mode: 'cells',
  size: { columns: 56, rows: 32 },
  canvas: null,
  words: null,
  rgba: null,
  cells: null,
  source: null,
  drawnFor: '',
  cost: 0,
  pace: { quality: 0, slow: 0, quick: 0 },
  timer: null,
  last: 0,
  ticks: 0,
  t0: 0,
  isPainting: false,
  refusals: 0,
  seen: unseen(),
  awaySince: null,
  isAutoPaused: false,
  hud: '',
  hudAt: 0,
  shown: 0,
  isFullscreen: true,
  fittedTo: null,
}

export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    try {
      state.best = bestOf(await $.store.get('best'))
    } catch {
      // Not readable now; a game's end reads the store again before writing.
    }
    try {
      await $.command.register({
        name: 'bricks',
        description: 'Play Brickfall, a brick breaker, in a pane',
        argumentHint: '[new|quit]',
        immediate: true,
      })
    } catch {
      // The name is taken; nothing else opens the pane.
    }
    return result
  })

  on('command.run', { command: 'bricks' }, async ($, e) => {
    const asked = parseArgs(e.args)
    if ('error' in asked) return { text: asked.error }
    if (asked.action === 'quit') {
      await closeGame($)
      try {
        await $.ui.close({ id: PANE })
      } catch {
        // Not open.
      }
      return { text: 'Brickfall has closed.' }
    }
    const surfaces = await $.session.surfaces()
    if (!surfaces.includes('terminal')) return { text: NO_SCREEN }
    state.isFullscreen = e.presentation.isFullscreen
    const [term, termProgram, prefer] = await Promise.all([
      $.env.get('TERM').catch(() => undefined),
      $.env.get('TERM_PROGRAM').catch(() => undefined),
      $.env.get('BRICKFALL_SCREEN').catch(() => undefined),
    ])
    state.mode = drawsImages(term, termProgram, prefer) ? 'image' : 'cells'
    state.drawnFor = ''
    if (asked.action === 'new' && state.game !== null) await recordBest($)
    if (state.game === null || asked.action === 'new') deal()
    await openPane($)
    focusSoon($, 0)
    startLoop($)
    return {}
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const elements = $.ui.resolve(e)
    // The surface decides; the `in` checks only tell the types what it decided.
    if (e.surface !== 'terminal' || !('Raster' in elements) || !('Image' in elements) || !('Client' in elements)) {
      return elements.Text({ children: [NO_SCREEN] })
    }
    const { Box, Text, Button, Raster, Image, Client } = elements
    if (e.viewport?.isFullscreen !== undefined) state.isFullscreen = e.viewport.isFullscreen
    const size = screenSize(e.props.bodyColumns, e.props.scroll.bodyRows, state.mode)
    if (size.columns !== state.size.columns || size.rows !== state.size.rows) state.size = size
    // A dock wider than the field the height allows: ask for the width the
    // field needs, once per size, so the transcript keeps the rest.
    if (e.props.placement === 'dock' && e.props.bodyColumns > size.columns + FIT_SLACK && state.fittedTo !== size.columns) {
      state.fittedTo = size.columns
      fitPane($, size.columns)
    }
    const g = state.game ?? deal()
    drawFrame(g, Date.now())
    const hud = hudOf(g, state.best, state.shown)
    state.hud = hudText(hud)
    const buttons = BUTTONS.map((b) =>
      Button({
        key: 'act-' + b.hotkey,
        label: b.label,
        hotkey: b.hotkey,
        plain: true,
        dimColor: b.act === 'left' || b.act === 'right',
        ...(b.autoFocus ? { autoFocus: true } : {}),
        onPress: () => {
          act($, b.act)
        },
      }),
    )
    const screen =
      state.mode === 'image' && state.source !== null
        ? Image({ key: SCREEN, source: state.source, columns: size.columns, rows: size.rows, alt: TITLE })
        : Raster({ key: SCREEN, columns: size.columns, rows: size.rows, cells: state.cells ?? '' })
    return Box({
      flexDirection: 'column',
      children: [
        Box({ flexDirection: 'row', children: hud.map((part) => Text({ color: part.color, wrap: 'truncate-end', children: [part.text] })) }),
        // The field, and over it the pointer's layer, which draws nothing.
        Box({
          width: size.columns,
          height: size.rows,
          children: [
            screen,
            Box({
              position: 'absolute',
              top: 0,
              left: 0,
              width: size.columns,
              height: size.rows,
              children: [Client({ key: LOOK, module: './pad.ts', props: { role: 'look' } satisfies PadProps, width: size.columns, height: size.rows })],
            }),
          ],
        }),
        Client({ key: STRIP, module: './pad.ts', props: { role: 'strip', hint: hintFor(state.isFullscreen) } satisfies PadProps }),
        Box({ flexDirection: 'row', columnGap: 2, children: buttons }),
      ],
    })
  })

  // The overlay posts the pointer and the acts it took.
  on('ui.message', async ($, e, next) => {
    const result = await next(e)
    if (e.requestId !== PANE || (e.element !== LOOK && e.element !== STRIP)) return result
    const pad = padOf(e.data)
    const g = state.game
    if (pad === null || g === null) return result
    // Each instance numbers its own acts.
    const fresh = freshActs(pad, state.seen[e.element])
    state.seen[e.element] = fresh.seen
    if (e.element === LOOK) {
      if (pad.x !== null && pad.isInside !== false) aim(g, pad.x * W)
      if (pad.isInside === false) state.awaySince ??= Date.now()
      if (pad.isInside === true) {
        state.awaySince = null
        if (state.isAutoPaused) {
          state.isAutoPaused = false
          g.isPaused = false
        }
      }
    }
    for (const a of fresh.acts) act($, a)
    return result
  })

  // A pane closes whatever this hook does: should it fail, the close goes on.
  on('ui.close', async ($, e, next) => {
    const result = await next(e)
    if (e.id === PANE) await closeGame($)
    return result
  }).catch((_$, e, next) => next(e))

  on('session.end', async ($, e, next) => {
    stopLoop()
    if (state.game !== null) await recordBest($)
    return next(e)
  })
}

// No act seen yet from either overlay instance: each numbers its own.
function unseen(): Record<PadProps['role'], number> {
  return { look: 0, strip: 0 }
}

// A new game, its first round served.
function deal(): Game {
  const g = newGame(Date.now() & 0x7fffffff)
  state.game = g
  state.shown = 0
  state.isAutoPaused = false
  state.awaySince = null
  return g
}

function act($: EngineInterface, a: Act): void {
  const g = state.game
  if (g === null) return
  switch (a) {
    case 'left':
      nudge(g, -1)
      return
    case 'right':
      nudge(g, 1)
      return
    case 'fire':
      if (g.phase === 'over') {
        void recordBest($)
        deal()
        return
      }
      if (g.isPaused) state.isAutoPaused = false
      press(g)
      return
    case 'pause':
      state.isAutoPaused = false
      togglePause(g)
      return
    case 'new':
      void recordBest($)
      deal()
      return
    default:
      a satisfies never
  }
}

// Draw the game into the canvas for the screen's size and keep the result as
// the screen's next cells or picture.
function drawFrame(g: Game, now: number): void {
  const size = state.size
  const key = `${state.mode}:${size.columns}x${size.rows}:${state.pace.quality}`
  if (state.drawnFor !== key || state.canvas === null) {
    const pixels = pixelsOf(size, state.mode, state.pace.quality)
    state.canvas = makeCanvas(pixels.width, pixels.height)
    state.words = null
    state.rgba = null
    state.drawnFor = key
  }
  const canvas = state.canvas
  draw(canvas, g, (now - state.t0) / 1000)
  if (state.mode === 'image') {
    state.rgba = toRgba(canvas, state.rgba ?? undefined)
    state.source = { rgba: base64(state.rgba), width: canvas.w, height: canvas.h }
  } else {
    state.words = toCells(canvas, state.words ?? undefined)
    state.cells = cellsOf(state.words)
  }
}

function startLoop($: EngineInterface): void {
  if (state.timer !== null) return
  const now = Date.now()
  state.last = now
  if (state.t0 === 0) state.t0 = now
  try {
    state.timer = $.clock.every(TICK_MS, () => tick($))
  } catch {
    // No timer: the field stays as drawn.
  }
}

function stopLoop(): void {
  if (state.timer !== null) state.timer.cancel()
  state.timer = null
  state.isPainting = false
}

// One step of the loop: move the game on by the time since the last, then
// paint a frame when the screen is free for one.
function tick($: EngineInterface): void {
  const g = state.game
  if (g === null) return
  const now = Date.now()
  const dt = Math.max(0, (now - state.last) / 1000)
  state.last = now
  if (state.awaySince !== null && now - state.awaySince > AWAY_MS && g.phase === 'play' && !g.isPaused) {
    g.isPaused = true
    state.isAutoPaused = true
  }
  step(g, dt)
  const events = drainEvents(g)
  if (events.includes('over') || events.includes('level')) void recordBest($)
  const isIdle = (g.isPaused || g.phase === 'serve' || g.phase === 'over') && g.particles.length === 0
  state.ticks += 1
  const every = isIdle ? Math.max(IDLE_FRAME_TICKS, frameTicks(state.mode, state.cost)) : frameTicks(state.mode, state.cost)
  if (!state.isPainting && state.ticks % every === 0) paint($, g, now)
  if (now - state.hudAt >= HUD_MS) {
    state.shown = rollScore(state.shown, g.score)
    const hud = hudText(hudOf(g, state.best, state.shown))
    if (hud !== state.hud) {
      state.hud = hud
      state.hudAt = now
      $.ui.invalidate('ui.render')
    }
  }
}

// Paint the next frame. A blit resolves once Claude Code has painted it, so
// one is in flight at a time and the frames in between are never drawn. The
// strip (pad.ts) keeps Claude Code drawing frames.
function paint($: EngineInterface, g: Game, now: number): void {
  drawFrame(g, now)
  measure(Date.now() - now)
  const size = state.size
  const isImage = state.mode === 'image'
  const source = state.source
  const cells = state.cells
  if (isImage ? source === null : cells === null) return
  state.isPainting = true
  const blit =
    isImage && source !== null
      ? $.ui.blit({ requestId: PANE, key: SCREEN, source, columns: size.columns, rows: size.rows })
      : $.ui.blit({ requestId: PANE, key: SCREEN, cells: cells ?? '', columns: size.columns, rows: size.rows })
  blit
    .then((result) => refused($, g, 'deny' in result && result.deny !== undefined, isImage))
    .catch(() => undefined)
    .finally(() => {
      state.isPainting = false
    })
}

// Keep the recent cost of a frame, and let the picture's quality follow it.
function measure(ms: number): void {
  state.cost = state.cost === 0 ? ms : state.cost * 0.8 + ms * 0.2
  if (state.mode === 'image') state.pace = nextPace(state.pace, state.cost)
}

// Refused blit after blit: a picture the terminal does not draw after all
// goes back to the cells; a field nobody can see (the pane hidden behind
// another) pauses the game.
function refused($: EngineInterface, g: Game, isRefused: boolean, isImage: boolean): void {
  state.refusals = isRefused ? state.refusals + 1 : 0
  if (state.refusals >= HIDDEN_REFUSALS && g.phase === 'play' && !g.isPaused) g.isPaused = true
  if (isImage && state.refusals >= IMAGE_REFUSALS && state.mode === 'image') {
    state.mode = 'cells'
    state.source = null
    state.drawnFor = ''
    state.refusals = 0
    $.ui.invalidate('ui.render')
  }
}

// Keep the game's score when it beats the record. The store is read again
// first, so a read that failed at session start never costs a stored record;
// when it cannot be read now, the score stands for this session only.
async function recordBest($: EngineInterface): Promise<void> {
  const g = state.game
  if (g === null) return
  const best = betterBest(state.best, g.score, g.level)
  if (best === state.best) return
  state.best = best
  try {
    const stored = bestOf(await $.store.get('best'))
    const merged = stored !== null && best !== null && stored.score >= best.score ? stored : best
    state.best = merged
    await $.store.set('best', merged)
  } catch {
    // Not stored; the score still stands for this session.
  }
}

// The pane closed (or /bricks quit): stop the loop, keep the game paused for
// /bricks to bring back, and keep its score if it is a record.
async function closeGame($: EngineInterface): Promise<void> {
  stopLoop()
  const g = state.game
  if (g === null) return
  if (g.phase === 'play') g.isPaused = true
  state.seen = unseen()
  state.fittedTo = null
  await recordBest($)
}

// Open the pane, or bring the open one forward, with the keyboard if it can;
// at the width it was fitted to, once it has been.
async function openPane($: EngineInterface): Promise<void> {
  const size = paneRequest()
  try {
    // No closeOnEscape: Escape at an empty prompt would close the pane and
    // end the round. /bricks quit or ctrl+x x close it.
    await $.ui.open({ id: PANE, title: TITLE, focus: true, rows: size.rows, columns: state.fittedTo ?? size.columns })
  } catch {
    // Refused; the pane stays as it was.
  }
  $.ui.invalidate('ui.render')
}

function fitPane($: EngineInterface, columns: number): void {
  try {
    $.clock.after(0, async () => {
      try {
        await $.ui.open({ id: PANE, title: TITLE, columns })
      } catch {
        // Refused; the pane keeps its width.
      }
    })
  } catch {
    // No timer; the pane keeps its width.
  }
}

// Ask for the keyboard again once /bricks has returned, while the pane is
// open and still without it; never reopen a pane the person has closed.
function focusSoon($: EngineInterface, attempt: number): void {
  const wait = FOCUS_RETRIES_MS[attempt]
  if (wait === undefined) return
  try {
    $.clock.after(wait, () => void refocus($, attempt))
  } catch {
    // No timer; a click on the pane gives it the keyboard.
  }
}

async function refocus($: EngineInterface, attempt: number): Promise<void> {
  try {
    const pane = (await $.ui.panes()).find((p) => p.id === PANE)
    if (pane === undefined || pane.isFocused) return
    await openPane($)
    focusSoon($, attempt + 1)
  } catch {
    // The panes cannot be listed; a click on the pane gives it the keyboard.
  }
}

