// brickfall: the game itself, with no drawing and no $. A field of world
// units (W by H) the renderer scales to the pane; the hooks module steps it
// on a timer and hands it the pointer and the keys. Everything random comes
// from the game's own seed, so the tests replay it exactly.

export type Rgb = readonly [number, number, number]
export type Point = { x: number; y: number }

export type BrickKind = 'color' | 'silver' | 'gold' | 'volt'
export type Brick = { kind: BrickKind; color: Rgb; hits: number; points: number; flash: number }
export const CAPSULE_KINDS = ['laser', 'enlarge', 'catch', 'slow', 'split', 'fire', 'life', 'giant', 'barrier', 'zap', 'nova', 'magnet', 'double'] as const
export type CapsuleKind = (typeof CAPSULE_KINDS)[number]
// The capsules that change the paddle itself, and the paddle without one.
export type PaddleMode = 'normal' | Extract<CapsuleKind, 'laser' | 'catch' | 'enlarge'>
// Powers that last a while (FEVER comes from gems, not a capsule), and powers
// that last so many hits.
export const TIMED = ['fire', 'giant', 'magnet', 'double', 'fever'] as const
export type Timed = (typeof TIMED)[number]
export const CHARGED = ['barrier', 'nova'] as const
export type Charged = (typeof CHARGED)[number]
// What a step reports to the hooks module.
export type GameEvent = 'paddle' | 'barrier' | 'clink' | 'break' | 'combo' | 'volt' | 'nova' | 'zap' | 'clear' | 'lose' | 'over' | 'level' | 'capsule' | 'gem' | 'fever' | 'laser'
export type Ball = { x: number; y: number; vx: number; vy: number; isStuck: boolean; offset: number; stuckFor: number; trail: Point[] }
export type Capsule = { x: number; y: number; vx: number; kind: CapsuleKind; age: number }
export type Gem = { x: number; y: number; vx: number; vy: number; color: Rgb; age: number }
export type Laser = { x: number; y: number }
export type ParticleKind = 'spark' | 'shard' | 'ring'
export type Particle = { x: number; y: number; vx: number; vy: number; life: number; max: number; color: Rgb; size: number; kind: ParticleKind; gravity: number }
export type Floater = { x: number; y: number; text: string; life: number; max: number; color: Rgb; size: number }
// A burst of light where something hit, a broken brick's last flash, a bolt
// of lightning: effects that only age.
export type Light = { x: number; y: number; color: Rgb; radius: number; life: number; max: number }
export type Ghost = { col: number; row: number; color: Rgb; life: number; max: number }
export type Bolt = { x0: number; y0: number; x1: number; y1: number; life: number; max: number; seed: number }
export type Phase = 'serve' | 'play' | 'lost' | 'clear' | 'over'
export type Blast = { col: number; row: number; at: number }

export type Game = {
  seed: number
  level: number
  lives: number
  score: number
  phase: Phase
  phaseTime: number
  // Seconds of play, paused time excluded: what particles and flashes age by.
  time: number
  isPaused: boolean
  paddle: { x: number; width: number; target: number; mode: PaddleMode; glow: number; cooldown: number; dip: number }
  balls: Ball[]
  speed: number
  bricks: (Brick | null)[]
  rows: number
  capsules: Capsule[]
  gems: Gem[]
  lasers: Laser[]
  particles: Particle[]
  floaters: Floater[]
  lights: Light[]
  ghosts: Ghost[]
  bolts: Bolt[]
  blasts: Blast[]
  flash: number
  // The walls light up in the colour of what just broke.
  pulse: number
  pulseColor: Rgb
  // Bricks broken since the ball last touched the paddle: the combo.
  chain: number
  // Seconds left of each timed power, hits left of each charged one.
  timers: Record<Timed, number>
  charges: Record<Charged, number>
  // Gems caught toward the next fever, and in all.
  gemMeter: number
  gemsTotal: number
  sincePaddle: number
  trailClock: number
  // While a zap or a blast breaks many bricks at once, their points add up
  // here, to fly off as one number.
  batch: { points: number; x: number; y: number; n: number } | null
  // What happened this step, for the hooks module (a best score, a sound).
  events: GameEvent[]
}

// The field, in world units: Arkanoid's own 224 by 256, walls on three sides.
export const W = 224
export const H = 256
export const WALL = 8
export const COLS = 13
export const BRICK_W = 16
export const BRICK_H = 8
export const BRICK_TOP = 32
export const PADDLE_Y = 236
export const PADDLE_H = 6
export const BALL_R = 2.5
export const GIANT_R = 6
export const BARRIER_Y = 250
export const PADDLE_WIDTH = { normal: 32, enlarge: 48 } as const
export const FEVER_GEMS = 12

const STEP = 1 / 240
const MAX_DT = 0.05
const MAX_BALLS = 9
const MAX_PARTICLES = 1400
export const MAX_LIVES = 9
export const START_LIVES = 3
const CAPSULE_SPEED = 46
const CAPSULE_CHANCE = 0.2
const GEM_CHANCE = 0.4
export const GEM_POINTS = 500
export const CAPSULE_POINTS = 2500
const LASER_SPEED = 420
const LASER_COOLDOWN = 0.2
const CATCH_RELEASE = 2.5
const LOST_SECONDS = 1.6
const CLEAR_SECONDS = 2.4
const VOLT_DELAY = 0.07
const NUDGE = 14
const MAX_ANGLE = (58 * Math.PI) / 180
const MIN_VY = 0.3
export const SECONDS: Readonly<Record<Timed, number>> = { fire: 8, giant: 10, magnet: 12, double: 12, fever: 8 }
export const CHARGES: Readonly<Record<Charged, number>> = { barrier: 3, nova: 3 }
export const ZAP_TARGETS = 8
// How far in from the paddle's ends its laser guns sit.
export const LASER_INSET = 3
// The combo: every COMBO_STEP bricks before the paddle add one to the
// multiplier, up to MAX_MULT; COMBO_FULL bricks reach it.
export const COMBO_STEP = 5
export const MAX_MULT = 4
export const COMBO_FULL = (MAX_MULT - 1) * COMBO_STEP
// Half the size of a falling capsule and of a gem, and how far past the
// paddle's ends each is still caught.
export const CAPSULE_HALF = { w: 6.5, h: 3.2 } as const
export const GEM_HALF = { w: 3, h: 4 } as const
const CATCH_MARGIN = { capsule: 4.5, gem: 6 } as const
// A floater this size or more is a headline (COMBO, FEVER): it lasts longer
// and rises slower.
export const BIG_FLOATER = 3.5
export const FEVER_COLOR: Rgb = [255, 120, 220]

// Points: a brick's worth is ten times Arkanoid's, so the numbers that fly
// off it are big ones.
export const COLORS = {
  W: { color: [242, 242, 255], points: 500 },
