// The letters of the other bricks.
const SPECIAL = { S: 'silver', X: 'gold', V: 'volt' } as const satisfies Readonly<Record<string, BrickKind>>

// Whether `ch` stands for a brick in a round's rows.
export function isBrickLetter(ch: string): boolean {
  return isColorLetter(ch) || isSpecialLetter(ch)
}

function isColorLetter(ch: string): ch is keyof typeof COLORS {
  return Object.hasOwn(COLORS, ch)
}

function isSpecialLetter(ch: string): ch is keyof typeof SPECIAL {
  return Object.hasOwn(SPECIAL, ch)
}
