// X gold (never breaks), V volt (blows up its neighbours), `.` nothing.
// After the last the rounds come round again, faster and with harder silver.
export type Level = { name: string; rows: readonly string[] }
export type Wall = { bricks: (Brick | null)[]; rows: number }

