// A small, fast generator whose whole state is the game's `seed`.
export function random(g: Game): number {
  g.seed = (g.seed + 0x6d2b79f5) | 0
  let t = g.seed
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

function range(g: Game, lo: number, hi: number): number {
  return lo + (hi - lo) * random(g)
}

export function levelOf(level: number): Level {
  const index = (((level - 1) % LEVELS.length) + LEVELS.length) % LEVELS.length
  return LEVELS[index] ?? LEVELS[0]
}

export function silverHits(level: number): number {
  return 2 + Math.floor((level - 1) / 8)
}

// Speed in world units a second: where a round starts, and as fast as it goes.
export function baseSpeed(level: number): number {
  return Math.min(190, 118 + (level - 1) * 6)
}

export function maxSpeed(level: number): number {
  return Math.min(300, 236 + (level - 1) * 5)
}

export function bricksOf(level: number): Wall {
  return bricksFrom(levelOf(level).rows, level)
}

// A wall of bricks from a round's rows, as round `level` makes them.
export function bricksFrom(lines: readonly string[], level: number): Wall {
  const rows = lines.length
  const bricks: (Brick | null)[] = []
  for (const line of lines) {
    for (let col = 0; col < COLS; col++) bricks.push(brickOf(line[col] ?? '.', level))
  }
  return { bricks, rows }
}

function brickOf(ch: string, level: number): Brick | null {
  if (isColorLetter(ch)) {
    const c = COLORS[ch]
    return { kind: 'color', color: c.color, hits: 1, points: c.points, flash: 0 }
  }
  if (!isSpecialLetter(ch)) return null
  const kind = SPECIAL[ch]
  switch (kind) {
    case 'silver':
      return { kind, color: SILVER, hits: silverHits(level), points: 500 * level, flash: 0 }
    case 'gold':
      return { kind, color: GOLD, hits: Infinity, points: 0, flash: 0 }
    case 'volt':
      return { kind, color: VOLT, hits: 1, points: 1500, flash: 0 }
  }
}

// Gold never breaks; everything else does, in its own number of hits.
export function isBreakable(b: Brick): boolean {
  return b.kind !== 'gold'
}

export function newGame(seed: number, level = 1): Game {
  const { bricks, rows } = bricksOf(level)
  const g: Game = {
    seed: seed | 0,
    level,
    lives: START_LIVES,
    score: 0,
    phase: 'serve',
    phaseTime: 0,
    time: 0,
    isPaused: false,
    paddle: { x: W / 2, width: PADDLE_WIDTH.normal, target: W / 2, mode: 'normal', glow: 0, cooldown: 0, dip: 0 },
    balls: [],
    speed: baseSpeed(level),
    bricks,
    rows,
    capsules: [],
    gems: [],
    lasers: [],
    particles: [],
    floaters: [],
    lights: [],
    ghosts: [],
    bolts: [],
    blasts: [],
    flash: 0,
    pulse: 0,
    pulseColor: [255, 255, 255],
    chain: 0,
    timers: noTimers(),
    charges: { barrier: 0, nova: 0 },
    gemMeter: 0,
    gemsTotal: 0,
    sincePaddle: 0,
    trailClock: 0,
    batch: null,
    events: [],
  }
  serve(g)
  return g
}

// A fresh ball sitting on the paddle, a round's name over the field. The
// barrier and the gems caught so far stay; the timed powers go.
function serve(g: Game): void {
  g.phase = 'serve'
  g.phaseTime = 0
  g.speed = baseSpeed(g.level)
  g.timers = noTimers()
  g.charges.nova = 0
  g.chain = 0
  g.capsules = []
  g.gems = []
  g.lasers = []
  g.paddle.mode = 'normal'
  g.balls = [ballAt(g.paddle.x, PADDLE_Y - ballRadius(g), 0, 0, true)]
}

function noTimers(): Record<Timed, number> {
  return { fire: 0, giant: 0, magnet: 0, double: 0, fever: 0 }
}

export function ballAt(x: number, y: number, vx = 0, vy = 0, isStuck = false): Ball {
  return { x, y, vx, vy, isStuck, offset: 0, stuckFor: 0, trail: [] }
}

export function isOn(g: Game, power: Timed | Charged): boolean {
  return isTimed(power) ? g.timers[power] > 0 : g.charges[power] > 0
}

function isTimed(power: CapsuleKind | Timed | Charged): power is Timed {
  return TIMED.some((p) => p === power)
}

function isCharged(power: CapsuleKind | Timed | Charged): power is Charged {
  return CHARGED.some((p) => p === power)
}

// The brick cell a world point is in (off the wall's grid, out of range).
export function cellOf(x: number, y: number): { col: number; row: number } {
  return { col: Math.floor((x - WALL) / BRICK_W), row: Math.floor((y - BRICK_TOP) / BRICK_H) }
}

// Where a brick's cell sits in the game's flat list of bricks.
export function brickIndex(col: number, row: number): number {
  return row * COLS + col
}

// The middle of a brick's place on the wall.
export function brickCenter(col: number, row: number): Point {
  const r = brickRect(col, row)
  return { x: (r.x0 + r.x1) / 2, y: (r.y0 + r.y1) / 2 }
}

// A velocity turned by `a` radians.
function rotate(vx: number, vy: number, a: number): { vx: number; vy: number } {
  const cos = Math.cos(a)
  const sin = Math.sin(a)
  return { vx: vx * cos - vy * sin, vy: vx * sin + vy * cos }
}

export function breakableLeft(g: Game): number {
  let n = 0
  for (const b of g.bricks) if (b !== null && isBreakable(b)) n++
  return n
}

export function multiplier(chain: number): number {
  return Math.min(MAX_MULT, 1 + Math.floor(chain / COMBO_STEP))
}

// What points are worth right now: the combo, doubled by DOUBLE and by fever.
export function bonus(g: Game): number {
  return multiplier(g.chain) * doubling(g)
}

// DOUBLE and FEVER each double points, a brick's or a gem's.
function doubling(g: Game): number {
  return (isOn(g, 'double') ? 2 : 1) * (isOn(g, 'fever') ? 2 : 1)
}

export function ballRadius(g: Game): number {
  return isOn(g, 'giant') ? GIANT_R : BALL_R
}

// ---- input ----------------------------------------------------------------

// The pointer is over the field at world x: the paddle follows it.
export function aim(g: Game, x: number): void {
  g.paddle.target = clampPaddle(g, x)
}

// A key moved the paddle a step.
export function nudge(g: Game, dir: -1 | 1): void {
  g.paddle.target = clampPaddle(g, g.paddle.target + dir * NUDGE)
}

// Click, space or the launch button: launch a held ball, fire the laser, or
// go on after a pause.
export function press(g: Game): void {
  if (g.isPaused) {
    g.isPaused = false
    return
  }
  if (g.phase === 'over') return
  let launched = false
  for (const ball of g.balls) {
    if (ball.isStuck) {
      launch(g, ball)
      launched = true
    }
  }
  if (launched) {
    if (g.phase === 'serve') {
      g.phase = 'play'
      g.phaseTime = 0
    }
    return
  }
  if (g.paddle.mode === 'laser' && g.phase === 'play' && g.paddle.cooldown <= 0) {
    const half = g.paddle.width / 2 - LASER_INSET
    g.lasers.push({ x: g.paddle.x - half, y: PADDLE_Y }, { x: g.paddle.x + half, y: PADDLE_Y })
    g.paddle.cooldown = LASER_COOLDOWN
    g.events.push('laser')
    light(g, g.paddle.x - half, PADDLE_Y - 3, [255, 80, 80], 12, 0.12)
    light(g, g.paddle.x + half, PADDLE_Y - 3, [255, 80, 80], 12, 0.12)
  }
}

export function togglePause(g: Game): void {
  if (g.phase === 'over') return
  g.isPaused = !g.isPaused
}

function clampPaddle(g: Game, x: number): number {
  const half = g.paddle.width / 2
  return Math.max(WALL + half, Math.min(W - WALL - half, x))
}

// A held ball goes off at the angle its place on the paddle gives it, never
// quite straight up.
function launch(g: Game, ball: Ball): void {
  aimBall(ball, ball.offset / (g.paddle.width / 2), g.speed, 0.17)
  ball.isStuck = false
  ball.stuckFor = 0
}

// Send a ball up off the paddle: `rel` is where it is along the paddle, -1 at
// the left end to 1 at the right, and sets the angle from straight up. An
// angle under `least` (radians) is pushed out to a sure one.
function aimBall(ball: Ball, rel: number, speed: number, least = 0): void {
  let angle = Math.max(-1, Math.min(1, rel)) * MAX_ANGLE
  if (Math.abs(angle) < least) angle = (angle < 0 ? -1 : 1) * 0.32
  ball.vx = speed * Math.sin(angle)
  ball.vy = -speed * Math.cos(angle)
}

// ---- stepping -------------------------------------------------------------

// Move the game on by `dt` seconds of real time.
export function step(g: Game, dt: number): void {
  const real = Math.min(dt, MAX_DT)
  if (g.isPaused || g.phase === 'over') {
    ageEffects(g, g.phase === 'over' ? real : 0)
    return
  }
  let left = real
  while (left > 1e-9) {
    const h = Math.min(STEP, left)
    tick(g, h)
    left -= h
  }
}

function tick(g: Game, h: number): void {
  g.time += h
  g.phaseTime += h
  g.sincePaddle += h
  movePaddle(g, h)
  if (g.paddle.cooldown > 0) g.paddle.cooldown -= h
  for (const power of TIMED) g.timers[power] = Math.max(0, g.timers[power] - h)

  if (g.phase === 'lost' && g.phaseTime >= LOST_SECONDS) {
    if (g.lives > 0) serve(g)
    else {
      g.phase = 'over'
      g.phaseTime = 0
      g.events.push('over')
    }
  } else if (g.phase === 'clear' && g.phaseTime >= CLEAR_SECONDS) {
    g.level += 1
    const next = bricksOf(g.level)
    g.bricks = next.bricks
    g.rows = next.rows
    g.particles = []
    serve(g)
    g.events.push('level')
  }

  for (const ball of g.balls) moveBall(g, ball, h)
  const r = ballRadius(g)
  g.balls = g.balls.filter((b) => b.y - r <= H + 4)
  if (g.balls.length === 0 && (g.phase === 'play' || g.phase === 'serve')) loseLife(g)

  moveLasers(g, h)
  moveCapsules(g, h)
  moveGems(g, h)
  runBlasts(g)
  ageEffects(g, h)

  // Trails: one point every sixtieth of a second, the last ten kept; a
  // burning or charged ball sheds embers.
  g.trailClock += h
  if (g.trailClock >= 1 / 60) {
    g.trailClock = 0
    for (const ball of g.balls) {
      ball.trail.push({ x: ball.x, y: ball.y })
      if (ball.trail.length > 10) ball.trail.shift()
      if (ball.isStuck) continue
      if (isOn(g, 'fire')) ember(g, ball, random(g) < 0.5 ? [255, 120, 40] : [255, 70, 200])
      if (isOn(g, 'nova')) ember(g, ball, random(g) < 0.5 ? [255, 70, 40] : [255, 220, 120])
      if (isOn(g, 'fever')) ember(g, ball, hueOf(g.time * 2 + random(g)))
    }
  }
}

function ember(g: Game, ball: Ball, color: Rgb): void {
  const life = 0.3 + random(g) * 0.3
  addParticle(g, { x: ball.x, y: ball.y, vx: range(g, -25, 25), vy: range(g, -40, 5), life, max: life, color, size: 1.2, kind: 'spark', gravity: -30 })
}

function movePaddle(g: Game, h: number): void {
  const p = g.paddle
  const want = p.mode === 'enlarge' ? PADDLE_WIDTH.enlarge : PADDLE_WIDTH.normal
  p.width += (want - p.width) * Math.min(1, h * 10)
  p.target = clampPaddle(g, p.target)
  p.x += (p.target - p.x) * Math.min(1, h * 60)
  p.x = clampPaddle(g, p.x)
  if (p.glow > 0) p.glow = Math.max(0, p.glow - h * 3)
  if (p.dip > 0) p.dip = Math.max(0, p.dip - h * 12)
  for (const ball of g.balls) {
    if (!ball.isStuck) continue
    ball.x = p.x + ball.offset
    ball.y = PADDLE_Y - ballRadius(g)
    ball.stuckFor += h
    if (g.phase === 'play' && ball.stuckFor >= CATCH_RELEASE) launch(g, ball)
  }
}

function moveBall(g: Game, ball: Ball, h: number): void {
  if (ball.isStuck) return
  const r = ballRadius(g)
  ball.x += ball.vx * h
  ball.y += ball.vy * h

  // Walls.
  if (ball.x < WALL + r) {
    ball.x = WALL + r
    ball.vx = Math.abs(ball.vx)
    wallBounce(g, ball)
  } else if (ball.x > W - WALL - r) {
    ball.x = W - WALL - r
    ball.vx = -Math.abs(ball.vx)
    wallBounce(g, ball)
  }
  if (ball.y < WALL + r) {
    ball.y = WALL + r
    ball.vy = Math.abs(ball.vy)
    wallBounce(g, ball)
  }

  // The paddle: where it lands on it decides the angle.
  const p = g.paddle
  if (ball.vy > 0 && ball.y + r >= PADDLE_Y && ball.y - r <= PADDLE_Y + PADDLE_H && g.phase === 'play') {
    const half = p.width / 2
    if (ball.x >= p.x - half - r && ball.x <= p.x + half + r) {
      g.speed = Math.min(maxSpeed(g.level), g.speed + 2.5)
      aimBall(ball, (ball.x - p.x) / half, g.speed)
      ball.y = PADDLE_Y - r
      p.glow = 1
      p.dip = 1
      g.chain = 0
      g.sincePaddle = 0
      g.events.push('paddle')
      sparks(g, ball.x, PADDLE_Y, [120, 220, 255], 10, 70)
      light(g, ball.x, PADDLE_Y, [110, 210, 255], 22, 0.18)
      if (p.mode === 'catch') {
        ball.isStuck = true
        ball.offset = ball.x - p.x
        ball.stuckFor = 0
        ball.vx = 0
        ball.vy = 0
      }
    }
  }

  // The barrier under the paddle sends a ball back up, three times.
  if (isOn(g, 'barrier') && ball.vy > 0 && ball.y + r >= BARRIER_Y) {
    ball.y = BARRIER_Y - r
    ball.vy = -Math.abs(ball.vy)
    g.charges.barrier -= 1
    g.events.push('barrier')
    sparks(g, ball.x, BARRIER_Y, CAPSULES.barrier.color, 24, 120)
    light(g, ball.x, BARRIER_Y, CAPSULES.barrier.color, 40, 0.3)
    floater(g, ball.x, BARRIER_Y - 14, isOn(g, 'barrier') ? 'SAVED' : 'LAST SAVE', CAPSULES.barrier.color, 2.2)
  }

  hitBricks(g, ball, r)
}

// Keep the ball off flat, endless sideways runs, and nudge it out of loops
// between bricks that never break.
function wallBounce(g: Game, ball: Ball): void {
  const speed = Math.hypot(ball.vx, ball.vy) || g.speed
  if (Math.abs(ball.vy) < speed * MIN_VY) {
    ball.vy = (ball.vy < 0 ? -1 : 1) * speed * MIN_VY
    ball.vx = Math.sign(ball.vx || 1) * Math.sqrt(speed * speed - ball.vy * ball.vy)
  }
  if (g.sincePaddle > 20) {
    Object.assign(ball, rotate(ball.vx, ball.vy, range(g, -0.2, 0.2)))
  }
}

function brickAt(g: Game, col: number, row: number): Brick | null {
  if (col < 0 || col >= COLS || row < 0 || row >= g.rows) return null
  return g.bricks[brickIndex(col, row)] ?? null
}

export function brickRect(col: number, row: number): { x0: number; y0: number; x1: number; y1: number } {
  const x0 = WALL + col * BRICK_W
  const y0 = BRICK_TOP + row * BRICK_H
  return { x0, y0, x1: x0 + BRICK_W, y1: y0 + BRICK_H }
}

function hitBricks(g: Game, ball: Ball, r: number): void {
  const { col: c0, row: r0 } = cellOf(ball.x - r, ball.y - r)
  const { col: c1, row: r1 } = cellOf(ball.x + r, ball.y + r)
  let best: { col: number; row: number; dx: number; dy: number; d2: number; cx: number; cy: number } | null = null
  const touched: { col: number; row: number }[] = []
  for (let row = r0; row <= r1; row++) {
    for (let col = c0; col <= c1; col++) {
      if (brickAt(g, col, row) === null) continue
      const rect = brickRect(col, row)
      const cx = Math.max(rect.x0, Math.min(rect.x1, ball.x))
      const cy = Math.max(rect.y0, Math.min(rect.y1, ball.y))
      const dx = ball.x - cx
      const dy = ball.y - cy
      const d2 = dx * dx + dy * dy
      if (d2 >= r * r) continue
      touched.push({ col, row })
      if (best === null || d2 < best.d2) best = { col, row, dx, dy, d2, cx, cy }
    }
  }
  if (best === null) return
  const brick = brickAt(g, best.col, best.row)
  if (brick === null) return
  const isPierce = isOn(g, 'fire') && isBreakable(brick)
  // A giant ball breaks everything it touches; any other, the nearest.
  const hits = isOn(g, 'giant') ? touched : [{ col: best.col, row: best.row }]
  for (const t of hits) damage(g, t.col, t.row, isPierce ? 99 : 1)
  if (isOn(g, 'nova')) {
    g.charges.nova -= 1
    blast(g, best.col, best.row, 'nova')
  }
  if (isPierce) return

  // Bounce off the face the ball came through.
  let nx = best.dx
  let ny = best.dy
  if (best.d2 < 1e-9) {
    // The centre went inside: back out the way it came.
    nx = -ball.vx
    ny = -ball.vy
  }
  if (Math.abs(nx) > Math.abs(ny)) {
    ball.vx = Math.sign(nx) * Math.abs(ball.vx)
    if (best.d2 >= 1e-9) ball.x = best.cx + Math.sign(nx) * r
  } else {
    ball.vy = Math.sign(ny || 1) * Math.abs(ball.vy)
    if (best.d2 >= 1e-9) ball.y = best.cy + Math.sign(ny || 1) * r
  }
}

// A brick takes `power` hits: gold rings and stays, silver counts down, the
// rest break. A volt brick blows up its neighbours a moment later.
export function damage(g: Game, col: number, row: number, power: number): void {
  const brick = brickAt(g, col, row)
  if (brick === null) return
  const rect = brickRect(col, row)
  const { x: cx, y: cy } = brickCenter(col, row)
  brick.flash = 1
  if (!isBreakable(brick) || brick.hits - power > 0) {
    if (isBreakable(brick)) brick.hits -= power
    g.events.push('clink')
    sparks(g, cx, cy, brick.color, 10, 70)
    light(g, cx, cy, brick.color, 18, 0.14)
    return
  }
  g.bricks[brickIndex(col, row)] = null
  g.chain += 1
  const before = multiplier(g.chain - 1)
  const points = brick.points * bonus(g)
  g.score += points
  g.speed = Math.min(maxSpeed(g.level), g.speed + 0.4)
  for (const ball of g.balls) rescale(ball, g.speed)
  g.events.push('break')
  // The loud part: a burst of light, the brick's ghost and the walls
  // flashing its colour, shards and a ring, and the points. Nothing that
  // moves the field or stops the play: the ball must stay easy to follow.
  g.pulse = 1
  g.pulseColor = brick.color
  light(g, cx, cy, brick.color, 34, 0.26)
  g.ghosts.push({ col, row, color: brick.color, life: 0.2, max: 0.2 })
  if (g.ghosts.length > 40) g.ghosts.shift()
  shatter(g, rect.x0, rect.y0, brick.color)
  ring(g, cx, cy, brick.color, 16)
  if (g.batch !== null) {
    g.batch.points += points
    g.batch.n += 1
  } else {
    floater(g, cx, cy, '+' + points, brick.color, 2.4)
  }
  const mult = multiplier(g.chain)
  if (mult > before) {
    floater(g, W / 2, H / 2 + 6, 'COMBO X' + mult, [255, 214, 90], 4)
    g.flash = Math.min(1, g.flash + 0.25)
    g.events.push('combo')
  }
  if (brick.kind === 'volt') {
    g.blasts.push({ col, row, at: g.time + VOLT_DELAY })
  } else if (g.phase === 'play') {
    if (random(g) < CAPSULE_CHANCE && g.capsules.length < 3) g.capsules.push({ x: cx, y: cy, vx: 0, kind: pickCapsule(g), age: 0 })
    else if (random(g) < GEM_CHANCE) g.gems.push({ x: cx, y: cy, vx: range(g, -30, 30), vy: range(g, -60, -20), color: brick.color, age: 0 })
  }
  if (breakableLeft(g) === 0 && g.phase === 'play') clearLevel(g)
}

function rescale(ball: Ball, speed: number): void {
  if (ball.isStuck) return
  const now = Math.hypot(ball.vx, ball.vy)
  if (now < 1e-6) return
  ball.vx *= speed / now
  ball.vy *= speed / now
}

function runBlasts(g: Game): void {
  if (g.blasts.length === 0) return
  const due = g.blasts.filter((b) => b.at <= g.time)
  if (due.length === 0) return
  g.blasts = g.blasts.filter((b) => b.at > g.time)
  for (const b of due) blast(g, b.col, b.row, 'volt')
}

// How each kind of explosion looks: its ring and light, its two sprays of
// sparks, and the colour its added-up points fly off in.
const BLASTS: Readonly<Record<'volt' | 'nova', { color: Rgb; sparks: readonly [Rgb, Rgb]; points: Rgb }>> = {
  volt: { color: VOLT, sparks: [[190, 160, 255], [120, 240, 255]], points: [200, 170, 255] },
  nova: { color: CAPSULES.nova.band, sparks: [[255, 160, 60], [255, 240, 180]], points: [255, 190, 90] },
}

// An explosion on a brick: the eight around it break (gold excepted), a volt
// among them goes off in turn. A volt's own brick has already broken; a nova
// takes the brick it hit too.
function blast(g: Game, col: number, row: number, kind: 'volt' | 'nova'): void {
  const { x: cx, y: cy } = brickCenter(col, row)
  const look = BLASTS[kind]
  const color = look.color
  g.flash = Math.min(1, g.flash + 0.5)
  g.events.push(kind)
  ring(g, cx, cy, color, 34)
  ring(g, cx, cy, [255, 255, 255], 22)
  light(g, cx, cy, color, 64, 0.4)
  sparks(g, cx, cy, look.sparks[0], 34, 160)
  sparks(g, cx, cy, look.sparks[1], 18, 120)
  const outer = batchStart(g)
  for (let dr = -1; dr <= 1; dr++) {
    for (let dc = -1; dc <= 1; dc++) {
      const n = brickAt(g, col + dc, row + dr)
      if (n === null || !isBreakable(n)) continue
      damage(g, col + dc, row + dr, 99)
    }
  }
  batchEnd(g, outer, cx, cy, look.points)
}

function clearLevel(g: Game): void {
  g.phase = 'clear'
  g.phaseTime = 0
  g.capsules = []
  g.lasers = []
  for (const ball of g.balls) {
    ball.isStuck = true
    ball.offset = 0
    ball.vx = 0
    ball.vy = 0
  }
  g.balls = g.balls.slice(0, 1)
  g.events.push('clear')
  g.flash = 1
  for (let i = 0; i < 8; i++) {
    const x = range(g, 40, W - 40)
    const y = range(g, 50, 160)
    const hue = hueOf(i / 8)
    ring(g, x, y, hue, 40)
    light(g, x, y, hue, 50, 0.6)
    sparks(g, x, y, hue, 30, 140)
  }
}

function loseLife(g: Game): void {
  g.lives -= 1
  g.phase = 'lost'
  g.phaseTime = 0
  g.flash = 0.6
  g.capsules = []
  g.lasers = []
  g.timers.fire = 0
  g.events.push('lose')
  sparks(g, g.paddle.x, PADDLE_Y, [255, 120, 80], 50, 160)
  sparks(g, g.paddle.x, PADDLE_Y, [255, 230, 160], 26, 100)
  ring(g, g.paddle.x, PADDLE_Y, [255, 90, 60], 44)
  light(g, g.paddle.x, PADDLE_Y, [255, 90, 60], 70, 0.6)
}

function pickCapsule(g: Game): CapsuleKind {
  const kinds = CAPSULE_KINDS.filter((k) => !(k === 'split' && g.balls.length > 3))
  let total = 0
  for (const k of kinds) total += CAPSULES[k].weight
  let roll = random(g) * total
  for (const k of kinds) {
    roll -= CAPSULES[k].weight
    if (roll <= 0) return k
  }
  return 'enlarge'
}

// Where a magnet steers a falling drop: its sideways speed eases toward one
// that closes on the paddle, faster the further off it is, so it homes in
// without swinging past.
function steer(g: Game, x: number, vx: number, h: number): number {
  if (!isOn(g, 'magnet')) return vx * (1 - Math.min(1, h * 1.5))
  const want = Math.max(-220, Math.min(220, (g.paddle.x - x) * 4))
  return vx + (want - vx) * Math.min(1, h * 10)
}

// Whether a drop `half` in size at (x, y) touches the paddle, counting
// `margin` past its ends.
function isOnPaddle(g: Game, x: number, y: number, half: { w: number; h: number }, margin: number): boolean {
  return y + half.h >= PADDLE_Y && y - half.h <= PADDLE_Y + PADDLE_H && Math.abs(x - g.paddle.x) <= g.paddle.width / 2 + half.w + margin
}

function moveCapsules(g: Game, h: number): void {
  const kept: Capsule[] = []
  for (const c of g.capsules) {
    c.vx = steer(g, c.x, c.vx, h)
    c.x = Math.max(WALL + CAPSULE_HALF.w, Math.min(W - WALL - CAPSULE_HALF.w, c.x + c.vx * h))
    c.y += CAPSULE_SPEED * (isOn(g, 'magnet') ? 1.4 : 1) * h
    c.age += h
    if (g.phase === 'play' && isOnPaddle(g, c.x, c.y, CAPSULE_HALF, CATCH_MARGIN.capsule)) {
      apply(g, c.kind)
      continue
    }
    if (c.y - CAPSULE_HALF.h < H) kept.push(c)
  }
  g.capsules = kept
}

function moveGems(g: Game, h: number): void {
  const kept: Gem[] = []
  for (const gem of g.gems) {
    gem.vx = steer(g, gem.x, gem.vx, h)
    gem.vy = Math.min(80, gem.vy + 130 * h)
    gem.x += gem.vx * h
    gem.y += gem.vy * h
    gem.age += h
    if (gem.x < WALL + GEM_HALF.w) {
      gem.x = WALL + GEM_HALF.w
      gem.vx = Math.abs(gem.vx)
    } else if (gem.x > W - WALL - GEM_HALF.w) {
      gem.x = W - WALL - GEM_HALF.w
      gem.vx = -Math.abs(gem.vx)
    }
    if (g.phase === 'play' && isOnPaddle(g, gem.x, gem.y, GEM_HALF, CATCH_MARGIN.gem)) {
      collect(g, gem)
      continue
    }
    if (gem.y - GEM_HALF.h < H) kept.push(gem)
  }
  g.gems = kept
}

// A gem caught: points, a sparkle, and a step toward fever.
function collect(g: Game, gem: Gem): void {
  const points = GEM_POINTS * doubling(g)
  g.score += points
  g.gemsTotal += 1
  g.events.push('gem')
  sparks(g, gem.x, PADDLE_Y - 2, [255, 255, 255], 8, 60)
  sparks(g, gem.x, PADDLE_Y - 2, gem.color, 8, 80)
  light(g, gem.x, PADDLE_Y - 2, gem.color, 20, 0.2)
  floater(g, gem.x, PADDLE_Y - 16, '+' + points, gem.color, 1.8)
  if (isOn(g, 'fever')) return
  g.gemMeter += 1
  if (g.gemMeter >= FEVER_GEMS) {
    g.gemMeter = 0
    g.timers.fever = SECONDS.fever
    g.flash = 1
    g.events.push('fever')
    floater(g, W / 2, H / 2 - 10, 'FEVER!', FEVER_COLOR, 5)
    for (let i = 0; i < 6; i++) ring(g, W / 2, H / 2, hueOf(i / 6), 30 + i * 10)
  }
}

export function apply(g: Game, kind: CapsuleKind): void {
  const info = CAPSULES[kind]
  g.score += CAPSULE_POINTS
  g.events.push('capsule')
  floater(g, g.paddle.x, PADDLE_Y - 70, info.label + '!', info.color, 2.6)
  sparks(g, g.paddle.x, PADDLE_Y, info.color, 26, 110)
  ring(g, g.paddle.x, PADDLE_Y, info.color, 26)
  light(g, g.paddle.x, PADDLE_Y, info.color, 44, 0.35)
  if (isTimed(kind)) {
    g.timers[kind] = SECONDS[kind]
    return
  }
  if (isCharged(kind)) {
    g.charges[kind] = CHARGES[kind]
    return
  }
  const p = g.paddle
  switch (kind) {
    case 'laser':
    case 'catch':
    case 'enlarge':
      if (p.mode === 'catch' && kind !== 'catch') releaseAll(g)
      p.mode = kind
      return
    case 'slow':
      g.speed = Math.max(baseSpeed(g.level) * 0.75, g.speed * 0.65)
      for (const ball of g.balls) rescale(ball, g.speed)
      return
    case 'split': {
      releaseAll(g)
      const extra: Ball[] = []
      for (const ball of g.balls) {
        for (const a of [-0.45, 0.45]) {
          if (g.balls.length + extra.length >= MAX_BALLS) break
          const v = rotate(ball.vx, ball.vy, a)
          extra.push(ballAt(ball.x, ball.y, v.vx, v.vy))
        }
      }
      g.balls.push(...extra)
      return
    }
    case 'life':
      g.lives = Math.min(MAX_LIVES, g.lives + 1)
      return
    case 'zap':
      zap(g)
      return
    default:
      kind satisfies never
  }
}

// Lightning from the paddle to the bricks: up to eight of them, the nearest
// first, each struck down at once.
function zap(g: Game): void {
  const targets: { col: number; row: number; d: number }[] = []
  for (let row = 0; row < g.rows; row++) {
    for (let col = 0; col < COLS; col++) {
      const b = brickAt(g, col, row)
      if (b === null || !isBreakable(b)) continue
      targets.push({ col, row, d: Math.abs(brickCenter(col, row).x - g.paddle.x) + random(g) * 60 })
    }
  }
  targets.sort((a, b) => a.d - b.d)
  g.flash = Math.min(1, g.flash + 0.45)
  g.events.push('zap')
  const chosen = targets.slice(0, ZAP_TARGETS)
  const outer = batchStart(g)
  chosen.forEach((t, i) => {
    const { x, y } = brickCenter(t.col, t.row)
    // Fanned out across the paddle, so each bolt reads on its own.
    const from = g.paddle.x + (chosen.length > 1 ? (i / (chosen.length - 1) - 0.5) : 0) * g.paddle.width
    g.bolts.push({ x0: from, y0: PADDLE_Y - 2, x1: x, y1: y, life: 0.4, max: 0.4, seed: Math.floor(random(g) * 1e6) })
    light(g, x, y, CAPSULES.zap.color, 30, 0.35)
    damage(g, t.col, t.row, 99)
  })
  batchEnd(g, outer, W / 2, H / 2 + 40, CAPSULES.zap.band)
}

// Start adding up the points of many breaks; the batch already open, if a
// blast went off inside another, carries on.
function batchStart(g: Game): boolean {
  if (g.batch !== null) return false
  g.batch = { points: 0, x: 0, y: 0, n: 0 }
  return true
}

// The added-up points fly off as one big number, bigger the more there are.
function batchEnd(g: Game, isOuter: boolean, x: number, y: number, color: Rgb): void {
  if (!isOuter || g.batch === null) return
  const { points, n } = g.batch
  g.batch = null
  if (n === 0) return
  floater(g, x, y, '+' + points, color, Math.min(5, 2.6 + n * 0.25))
}

function releaseAll(g: Game): void {
  for (const ball of g.balls) if (ball.isStuck) launch(g, ball)
}

function moveLasers(g: Game, h: number): void {
  const kept: Laser[] = []
  for (const l of g.lasers) {
    l.y -= LASER_SPEED * h
    if (l.y < WALL) continue
    const { col, row } = cellOf(l.x, l.y)
    if (brickAt(g, col, row) !== null) {
      damage(g, col, row, 1)
      continue
    }
    kept.push(l)
  }
  g.lasers = kept
}

// ---- effects --------------------------------------------------------------

function ageEffects(g: Game, h: number): void {
  if (h <= 0) return
  for (const p of g.particles) {
    p.vy += p.gravity * h
    p.vx *= 1 - Math.min(1, h * 1.2)
    p.x += p.vx * h
    p.y += p.vy * h
    p.life -= h
  }
  g.particles = g.particles.filter((p) => p.life > 0)
  for (const b of g.bricks) if (b !== null && b.flash > 0) b.flash = Math.max(0, b.flash - h * 4)
  g.flash = Math.max(0, g.flash - h * 2.5)
  for (const f of g.floaters) {
    f.y -= (f.size >= BIG_FLOATER ? 6 : 16) * h
    f.life -= h
  }
  g.floaters = g.floaters.filter((f) => f.life > 0)
  for (const l of g.lights) l.life -= h
  g.lights = g.lights.filter((l) => l.life > 0)
  for (const gh of g.ghosts) gh.life -= h
  g.ghosts = g.ghosts.filter((gh) => gh.life > 0)
  for (const b of g.bolts) b.life -= h
  g.bolts = g.bolts.filter((b) => b.life > 0)
  g.pulse = Math.max(0, g.pulse - h * 4)
}

function addParticle(g: Game, p: Particle): void {
  if (g.particles.length >= MAX_PARTICLES) g.particles.shift()
  g.particles.push(p)
}

export function sparks(g: Game, x: number, y: number, color: Rgb, n: number, speed: number): void {
  for (let i = 0; i < n; i++) {
    const a = random(g) * Math.PI * 2
    const v = speed * (0.3 + random(g) * 0.7)
    const life = 0.35 + random(g) * 0.5
    addParticle(g, { x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life, max: life, color, size: 0.8 + random(g) * 0.9, kind: 'spark', gravity: 90 })
  }
}

// A broken brick: a spray of shards in its colour, falling, and a puff of
// white-hot sparks.
function shatter(g: Game, x0: number, y0: number, color: Rgb): void {
  for (let i = 0; i < 16; i++) {
    const x = x0 + 2 + random(g) * (BRICK_W - 4)
    const y = y0 + 1 + random(g) * (BRICK_H - 2)
    const life = 0.6 + random(g) * 0.7
    addParticle(g, { x, y, vx: range(g, -90, 90), vy: range(g, -110, 10), life, max: life, color, size: 1.3 + random(g) * 1.6, kind: 'shard', gravity: 260 })
  }
  sparks(g, x0 + BRICK_W / 2, y0 + BRICK_H / 2, mix(color, [255, 255, 255], 0.6), 16, 130)
}

function ring(g: Game, x: number, y: number, color: Rgb, size: number): void {
  addParticle(g, { x, y, vx: 0, vy: 0, life: 0.4, max: 0.4, color, size, kind: 'ring', gravity: 0 })
}

function light(g: Game, x: number, y: number, color: Rgb, radius: number, life: number): void {
  g.lights.push({ x, y, color, radius, life, max: life })
  if (g.lights.length > 24) g.lights.shift()
}

function floater(g: Game, x: number, y: number, text: string, color: Rgb, size: number): void {
  const life = size >= BIG_FLOATER ? 1.2 : 0.9
  // Keep it on the field, and stack it on any fresh one already there.
  const half = (text.length * 4 * size) / 2
  const fx = Math.max(WALL + half, Math.min(W - WALL - half, x))
  let at = y
  for (const f of g.floaters) if (Math.abs(f.x - fx) < half + 8 && Math.abs(f.y - at) < size * 6 && f.life > f.max * 0.4) at = f.y - size * 6.5
  g.floaters.push({ x: fx, y: Math.max(WALL + size * 4, at), text, life, max: life, color, size })
  if (g.floaters.length > 24) g.floaters.shift()
}

export function mix(a: Rgb, b: Rgb, t: number): Rgb {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]
}

// A rainbow colour (0 to 255 a channel) for `h` turns around the wheel.
export function hueOf(h: number): Rgb {
  return [127.5 + 127.5 * Math.cos(Math.PI * 2 * h), 127.5 + 127.5 * Math.cos(Math.PI * 2 * (h + 0.33)), 127.5 + 127.5 * Math.cos(Math.PI * 2 * (h + 0.67))]
}

// What the events of the steps since the last call were, and none kept.
export function drainEvents(g: Game): GameEvent[] {
  const events = g.events
  g.events = []
  return events
}

