// Pure functions for the brickfall mod: how big the screen is drawn, what the
// overlay's posts and the command's arguments say, the best score and the
// line over the field. Nothing here takes $, so the tests import it directly.

import type { ClientKeyEvent } from 'claude-code'

import { CAPSULES, CHARGED, FEVER_COLOR, FEVER_GEMS, H, MAX_LIVES, TIMED, W, isOn, levelOf } from './game'
import type { CapsuleKind, Game, Rgb } from './game'

export type Size = { columns: number; rows: number }
export type Pixels = { width: number; height: number }
export const ACTS = ['left', 'right', 'fire', 'pause', 'new'] as const
export type Act = (typeof ACTS)[number]
// How the field reaches the terminal: a picture (kitty, Ghostty) or cells.
export type ScreenMode = 'cells' | 'image'
export type Args = { action: 'play' } | { action: 'quit' } | { action: 'new' } | { error: string }
export type Best = { score: number; level: number } | null
// What the overlay posts (pad.ts builds it, padOf reads it back): its last
// few acts, numbered, where the pointer is across the field (0 to 1), and
// whether it is over the field; null where it has not said.
export type Numbered = { n: number; act: Act }
export type Pad = { acts: Numbered[]; x: number | null; isInside: boolean | null }
export type PadPost = { type: 'pad' } & Pad
export type Button = { label: string; hotkey: string; act: Act; autoFocus?: true }

// Rows the pane spends on things other than the screen: the score line over
// it, the overlay's hint line and the buttons under it.
export const CHROME_ROWS = 3

// The field is 224 by 256 world units; a terminal cell is about twice as
// tall as it is wide, so the screen is 1.75 times as many columns as rows.
const ASPECT = (W / H) * 2
const MIN_ROWS = 12
const MAX_COLUMNS = { cells: 512, image: 255 } as const
const MAX_ROWS = { cells: 256, image: 255 } as const

// The screen's size in cells for a pane body of `bodyColumns` by `bodyRows`:
// as tall as the body allows, as wide as that height needs.
export function screenSize(bodyColumns: number | undefined, bodyRows: number | undefined, mode: ScreenMode): Size {
  const width = Math.min(MAX_COLUMNS[mode], Math.max(Math.round(MIN_ROWS * ASPECT), Math.floor(bodyColumns ?? 80)))
  let rows = Math.min(MAX_ROWS[mode], Math.max(MIN_ROWS, Math.floor(bodyRows ?? 40) - CHROME_ROWS))
  let columns = Math.round(rows * ASPECT)
  if (columns > width) {
    columns = width
    rows = Math.max(MIN_ROWS, Math.floor(columns / ASPECT))
  }
  return { columns, rows }
}

// The canvas behind a screen: two pixels a cell each way for the quadrant
// cells; for a picture, the budget of pixels a frame (each frame's bytes cross
// to the terminal, which smooths what it stretches) times the share of it the
// current `quality` step keeps, four a column at most.
export const IMAGE_PIXELS = 36000
export const QUALITY = [1.6, 1.25, 1, 0.8] as const

export function pixelsOf(size: Size, mode: ScreenMode, quality = 0): Pixels {
  if (mode === 'cells') return { width: size.columns * 2, height: size.rows * 2 }
  const share = QUALITY[Math.max(0, Math.min(QUALITY.length - 1, quality))] ?? 1
  const scale = Math.min(4, Math.sqrt((IMAGE_PIXELS * share) / (size.columns * size.rows * 2)))
  return { width: Math.max(1, Math.round(size.columns * scale)), height: Math.max(1, Math.round(size.rows * 2 * scale)) }
}

// Keeping the game responsive on a busy machine. `cost` is the recent time a
// frame took to draw, in milliseconds. A picture gives up a little sharpness
// (never below QUALITY's last step: fewer pixels than that blurs) only when
// frames stay slow for a while, so a burst of fireworks never costs it; it
// steps back up as soon as the sharper step would still draw in time. Past
// that, both kinds of screen are painted every so many ticks instead. The
// game itself steps every tick either way.
export const FRAME_BUDGET_MS = 18
export const PACE_FRAMES = { down: 45, up: 30 } as const
export type Pace = { quality: number; slow: number; quick: number }

export function nextPace(pace: Pace, cost: number): Pace {
  const here = QUALITY[pace.quality] ?? 1
  const sharper = pace.quality > 0 ? (QUALITY[pace.quality - 1] ?? here) : null
  // Drawing cost follows the pixels drawn.
  const fits = sharper !== null && (cost * sharper) / here < FRAME_BUDGET_MS * 0.75
  const slow = cost > FRAME_BUDGET_MS ? pace.slow + 1 : 0
  const quick = fits ? pace.quick + 1 : 0
  if (slow >= PACE_FRAMES.down && pace.quality < QUALITY.length - 1) return { quality: pace.quality + 1, slow: 0, quick: 0 }
  if (quick >= PACE_FRAMES.up) return { quality: pace.quality - 1, slow: 0, quick: 0 }
  return { quality: pace.quality, slow, quick }
}

// Ticks between painted frames: cells every tick and a picture every other
// when frames are quick, up to one in three or four when they are slow.
export function frameTicks(mode: ScreenMode, cost: number): number {
  const need = Math.ceil(cost / 12)
  return mode === 'cells' ? Math.max(1, Math.min(3, need)) : Math.max(2, Math.min(4, need))
}

// The pane the command asks for: docked, a width the render then fits to
// the screen the pane's height allows; inline above the prompt, tall enough
// for a playable field.
export function paneRequest(): Size {
  return { columns: 64, rows: 28 + CHROME_ROWS }
}

// Whether the terminal draws pictures (kitty's graphics protocol): kitty and
// Ghostty say so in TERM or TERM_PROGRAM. `BRICKFALL_SCREEN` set to `cells`
// or `image` decides instead. A terminal that refuses the picture anyway
// still gets the cells: refused blits switch back.
export function drawsImages(term: string | undefined, termProgram: string | undefined, prefer: string | undefined): boolean {
  if (prefer === 'cells') return false
  if (prefer === 'image') return true
  return /kitty|ghostty/i.test(String(term ?? '')) || /ghostty/i.test(String(termProgram ?? ''))
}

// The buttons the hooks module draws under the screen, one an act. A pane's
// hotkeys reach only buttons the hooks module draws, and work before any
// click; a hotkey is one letter or digit, so space and the arrows cannot be
// one. Return presses the button holding the focus ring: `fire`'s.
const BUTTON: Readonly<Record<Act, Omit<Button, 'act'>>> = {
  left: { label: '← a', hotkey: 'a' },
  right: { label: 'd →', hotkey: 'd' },
  fire: { label: 'launch / fire', hotkey: 'w', autoFocus: true },
  pause: { label: 'pause', hotkey: 'p' },
  new: { label: 'new game', hotkey: 'n' },
}

export const BUTTONS: readonly Button[] = ACTS.map((act) => ({ act, ...BUTTON[act] }))

export function hotkeyOf(act: Act): string {
  return BUTTON[act].hotkey
}

// The act a key stands for once a click has given the overlay the keyboard:
// every button's hotkey, and the keys no button can have.
const KEYS: Readonly<Record<string, Act>> = {
  ...Object.fromEntries(ACTS.map((act) => [hotkeyOf(act), act])),
  left: 'left',
  right: 'right',
  ' ': 'fire',
  space: 'fire',
  up: 'fire',
  return: 'fire',
  enter: 'fire',
}

// The line under the field: how to play on the screen there is.
export function hintFor(isFullscreen: boolean): string {
  const key = hotkeyOf
  if (isFullscreen) return `the mouse steers · click launches and fires · leave the field to pause · ${key('pause')} pause · ${key('new')} new game`
  return `keys: ${key('left')} ${key('right')} steer · ${key('fire')} launches and fires · ${key('pause')} pause · /tui fullscreen adds the mouse`
}

export function actOf(e: ClientKeyEvent | null | undefined): Act | null {
  if (!e || typeof e.key !== 'string' || e.ctrl || e.meta) return null
  const key = e.key.length === 1 ? e.key.toLowerCase() : e.key
  return Object.hasOwn(KEYS, key) ? (KEYS[key] ?? null) : null
}

function isAct(value: unknown): value is Act {
  return typeof value === 'string' && ACTS.some((act) => act === value)
}

// The overlay's post, checked: its numbered acts, where the pointer is
// across the field (0 to 1, null when it has said nothing), and whether the
// pointer is over the field (null when it has not said).
export function padOf(message: unknown): Pad | null {
  if (!isRecord(message) || message['type'] !== 'pad') return null
  const acts: Numbered[] = []
  if (Array.isArray(message['acts'])) {
    for (const a of message['acts']) {
      if (!isRecord(a)) continue
      const n = a['n']
      const act = a['act']
      if (typeof n !== 'number' || !isAct(act)) continue
      acts.push({ n, act })
    }
  }
  const x = message['x']
  const inside = message['isInside']
  return {
    acts,
    x: typeof x === 'number' && Number.isFinite(x) ? Math.max(0, Math.min(1, x)) : null,
    isInside: typeof inside === 'boolean' ? inside : null,
  }
}

// A post replaces one not yet delivered, so each carries its last few acts,
// numbered: keep the ones newer than `seen`.
export function freshActs(pad: Pad, seen: number): { seen: number; acts: Act[] } {
  let last = seen
  const acts: Act[] = []
  for (const a of pad.acts) {
    if (a.n <= seen) continue
    acts.push(a.act)
    last = Math.max(last, a.n)
  }
  return { seen: last, acts }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

// `/bricks` alone opens the game; `/bricks new` deals a new one; `/bricks
// quit` closes it.
export function parseArgs(args: string | undefined): Args {
  const word = (args ?? '').trim().toLowerCase()
  if (word === '') return { action: 'play' }
  if (word === 'new' || word === 'restart') return { action: 'new' }
  if ('quit'.startsWith(word) || word === 'stop') return { action: 'quit' }
  return { error: `Unknown argument "${word}". Use /bricks, /bricks new or /bricks quit.` }
}

// The stored best, checked: anything else is no best at all.
export function bestOf(value: unknown): Best {
  if (!isRecord(value)) return null
  const score = value['score']
  const level = value['level']
  if (typeof score !== 'number' || !Number.isFinite(score) || score < 0) return null
  if (typeof level !== 'number' || !Number.isFinite(level) || level < 1) return null
  return { score: Math.floor(score), level: Math.floor(level) }
}

// The better of a stored best and a game's result: the same object when the
// game did not beat it.
export function betterBest(best: Best, score: number, level: number): Best {
  if (score <= 0) return best
  if (best !== null && best.score >= score) return best
  return { score, level }
}

export type HudPart = { text: string; color: string }

// The line over the field: score (`shown`, rolling up to the game's), best,
// round, lives, the gems toward a fever, and every power on.
export function hudOf(g: Game, best: Best, shown: number = g.score): HudPart[] {
  const parts: HudPart[] = [
    { text: String(Math.floor(shown)).padStart(7, '0'), color: '#ffe14a' },
    { text: ' best ' + String(Math.max(best?.score ?? 0, g.score)).padStart(7, '0'), color: '#8a8fb0' },
    { text: `  round ${g.level} · ${levelOf(g.level).name}`, color: '#9fe8ff' },
    { text: '  ' + '●'.repeat(Math.max(0, Math.min(MAX_LIVES, g.lives))), color: '#ff5c7a' },
    isOn(g, 'fever') ? { text: `  FEVER ${Math.ceil(g.timers.fever)}s`, color: hexOf(FEVER_COLOR) } : { text: `  ◆ ${g.gemMeter}/${FEVER_GEMS}`, color: '#7fe6ff' },
  ]
  return [...parts, ...powersOf(g)]
}

// Every power on: the timed ones with their seconds left (FEVER has its own
// slot), the charged ones with their hits left, and the paddle's.
function powersOf(g: Game): HudPart[] {
  const parts: HudPart[] = []
  for (const power of TIMED) {
    if (power === 'fever' || !isOn(g, power)) continue
    parts.push({ text: `  ${CAPSULES[power].label} ${Math.ceil(g.timers[power])}s`, color: hudColor(power) })
  }
  for (const power of CHARGED) if (isOn(g, power)) parts.push({ text: `  ${CAPSULES[power].label} x${g.charges[power]}`, color: hudColor(power) })
  const mode = g.paddle.mode
  if (mode !== 'normal') parts.push({ text: '  ' + CAPSULES[mode].label, color: hudColor(mode) })
  return parts
}

// A capsule's colour for the dark line over the field: the brighter of its
// body and its band.
function hudColor(kind: CapsuleKind): string {
  const { color, band } = CAPSULES[kind]
  return hexOf(luma(band) > luma(color) ? band : color)
}

function luma([r, g, b]: Rgb): number {
  return r * 0.3 + g * 0.59 + b * 0.11
}

function hexOf(color: Rgb): string {
  return '#' + color.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('')
}

// The score a line over the field shows, a step closer to the game's: a
// quarter of the way each time, so a big hit rolls up.
export function rollScore(shown: number, score: number): number {
  if (shown >= score) return score
  return Math.min(score, shown + Math.max(10, Math.ceil((score - shown) / 4)))
}

export function hudText(parts: readonly HudPart[]): string {
  return parts.map((p) => p.text).join('')
}

