// brickfall: the surface module taking the pointer and the keys. Two
// instances: `look`, laid over the screen and drawing nothing there, so the
// paddle follows the pointer across the field itself (a surface module
// cannot draw the screen, so it lies on top of it); and `strip`, the hint
// line under it. A click on either gives it the keyboard; what it takes goes
// to the hooks module, which plays it.

import type { ClientModule, ClientPointerEvent, ClientSurface } from 'claude-code'

import { actOf } from './lib'
import type { Act, Pad, PadPost } from './lib'

// What the hooks module hands each instance: the layer over the screen needs
// nothing; the strip shows the hint.
export type PadProps = { role: 'look' } | { role: 'strip'; hint: string }

type PadState = { beat: 0 | 1 }

// How many recent acts each post carries. A post replaces one not yet
// delivered, so each carries the last few, numbered, and the hooks module
// keeps the ones it has not seen.
const RECENT = 16

// Claude Code paints a blit at its next frame, and with nothing else moving
// it draws a frame only a few times a second. The strip redraws itself
// PUMP_MS apart (a blank that alternates between two blank characters) so
// every frame the game sends gets painted.
const PUMP_MS = 30
const BEATS = [' ', '⠀'] as const

// What an instance has to say: the post it sends, and its count of acts.
type Keys = Pad & { n: number }

// Each instance's act count, recent acts and pointer. Not state: they redraw
// nothing by themselves.
const pads = new WeakMap<ClientSurface<PadState>, Keys>()

function keysOf(surface: ClientSurface<PadState>): Keys {
  let keys = pads.get(surface)
  if (keys === undefined) {
    keys = { n: 0, acts: [], x: null, isInside: null }
    pads.set(surface, keys)
  }
  return keys
}

function send(surface: ClientSurface<PadState>, keys: Keys): void {
  const post: PadPost = { type: 'pad', acts: keys.acts, x: keys.x, isInside: keys.isInside }
  surface.post(post)
}

function acted(surface: ClientSurface<PadState>, act: Act): void {
  const keys = keysOf(surface)
  keys.n += 1
  keys.acts.push({ n: keys.n, act })
  if (keys.acts.length > RECENT) keys.acts.shift()
  send(surface, keys)
}

// Over the field: a move steers, a press launches or fires, and crossing the
// edge says whether the pointer is on the field at all.
function pointed(surface: ClientSurface<PadState>, e: ClientPointerEvent, isLook: boolean): void {
  const keys = keysOf(surface)
  if (e.type === 'down') {
    if (isLook) keys.x = across(surface, e)
    acted(surface, 'fire')
    return
  }
  if (!isLook) return
  if (e.type === 'move') {
    keys.x = across(surface, e)
    keys.isInside = true
  } else if (e.type === 'enter') {
    keys.isInside = true
  } else if (e.type === 'leave') {
    keys.isInside = false
  } else {
    return
  }
  send(surface, keys)
}

// Where the pointer is across the region, 0 at its left edge and 1 at its
// right, to the fraction of a cell where the terminal says.
function across(surface: ClientSurface<PadState>, e: ClientPointerEvent): number {
  const columns = surface.columns > 0 ? surface.columns : 1
  const x = e.fine ? e.fine.x : e.x + 0.5
  return Math.max(0, Math.min(1, x / columns))
}

function beat(surface: ClientSurface<PadState>): void {
  const state = surface.state ?? { beat: 0 }
  surface.setState({ beat: state.beat === 0 ? 1 : 0 })
}

const PadModule: ClientModule<PadProps, PadState> = (props, surface) => {
  const { Box, Text } = surface.elements
  const isLook = props.role === 'look'
  if (surface.state === undefined) {
    surface.setState({ beat: 0 })
    // One heartbeat is enough: the strip's.
    if (!isLook) surface.every(PUMP_MS, () => beat(surface))
  }
  surface.onKey((e) => {
    const act = actOf(e)
    if (act !== null) acted(surface, act)
  })
  surface.onPointer((e) => pointed(surface, e, isLook))
  // Over the screen: nothing drawn, so the picture shows through.
  if (props.role === 'look') return Box({ flexDirection: 'column' })

  const state = surface.state ?? { beat: 0 }
  return Box({
    flexDirection: 'row',
    children: [Text({ children: [BEATS[state.beat]] }), Text({ color: '#9fe8ff', wrap: 'truncate-end', children: [props.hint] })],
  })
}

export default PadModule

